namespace PathLens.Application.Storage;

/// <summary>
/// Private object storage. Keys are random and generated by the storage
/// implementation; user file names never become storage keys.
/// </summary>
public interface IObjectStorage
{
    Task<string> SaveAsync(Stream content, string contentType, CancellationToken cancellationToken);
    Task<Stream?> OpenReadAsync(string storageKey, CancellationToken cancellationToken);
    Task DeleteAsync(string storageKey, CancellationToken cancellationToken);
}
